            left:`${Math.random()*100}%`,top:`${Math.random()*100}%`,
            background:"#fff",opacity:Math.random()*.6+.1,
            animation:`twinkle ${2+Math.random()*4}s infinite alternate`,
            animationDelay:`${Math.random()*4}s`,
